// Original entry Debug writers and caller Formatter state; unchanged indexmap crate.
use indexmap::{IndexMap,map::Entry};use serde_json::{json,Value};
use std::{cell::RefCell,fmt::{self,Write},io::{self,BufRead},rc::Rc};
struct State{calls:Vec<Value>,out:String,fail:i64,chars:bool,post:Option<Value>}
struct Sink(Rc<RefCell<State>>);impl Sink{fn step(&self,kind:&str,text:&str)->fmt::Result{let mut s=self.0.borrow_mut();let n=s.calls.len();s.calls.push(json!({"Kind":kind,"Text":text}));if s.fail>=0&&n==s.fail as usize{return Err(fmt::Error)}s.out.push_str(text);Ok(())}}
impl Write for Sink{fn write_str(&mut self,s:&str)->fmt::Result{self.step("S",s)}fn write_char(&mut self,c:char)->fmt::Result{let chars=self.0.borrow().chars;let mut b=[0;4];self.step(if chars{"C"}else{"S"},c.encode_utf8(&mut b))}}
struct Observed<'a,T:?Sized>{value:&'a T,state:Rc<RefCell<State>>}impl<T:fmt::Debug+?Sized>fmt::Debug for Observed<'_,T>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{let result=self.value.fmt(f);self.state.borrow_mut().post=Some(json!({"Fill":f.fill().to_string(),"Align":f.align().map(|a|format!("{a:?}"))}));result}}
fn render<T:fmt::Debug>(value:&T,q:&Value)->Value{let state=Rc::new(RefCell::new(State{calls:Vec::new(),out:String::new(),fail:q["fail"].as_i64().unwrap(),chars:q["chars"].as_bool().unwrap(),post:None}));let item=Observed{value,state:state.clone()};let mut writer=Sink(state.clone());let result=match q["format"].as_u64().unwrap(){0=>write!(&mut writer,"{item:?}"),1=>write!(&mut writer,"{item:#?}"),2=>write!(&mut writer,"{item:x?}"),3=>write!(&mut writer,"{item:X?}"),4=>write!(&mut writer,"{item:+08x?}"),5=>write!(&mut writer,"{item:+#08X?}"),6=>write!(&mut writer,"{item:*^9?}"),7=>write!(&mut writer,"{item:0>12?}"),8=>write!(&mut writer,"{item:\n^#12?}"),9=>write!(&mut writer,"{item:.3?}"),10=>write!(&mut writer,"{item:+?}"),11=>write!(&mut writer,"{item:-?}"),_=>panic!("bad format")};let s=state.borrow();json!({"calls":s.calls,"out":s.out,"failed":result.is_err(),"post":s.post})}
fn run(q:&Value)->Value{let mut map=IndexMap::from([(10u64,-26i32),(20,33)]);match q["kind"].as_str().unwrap(){"entry_occupied"=>render(&map.entry(10),q),"entry_vacant"=>render(&map.entry(7),q),"occupied"=>match map.entry(10){Entry::Occupied(e)=>render(&e,q),_=>unreachable!()},"vacant"=>match map.entry(7){Entry::Vacant(e)=>render(&e,q),_=>unreachable!()},"indexed"=>render(&map.get_index_entry(1).unwrap(),q),_=>panic!("bad kind")}}
fn main(){for line in io::stdin().lock().lines(){let q:Value=serde_json::from_str(&line.unwrap()).unwrap();println!("{}",json!({"request":q,"result":run(&q)}))}}
